const D = { energy:.6, scale:1, hue:215, speed:1, density:.5, x:.5, y:.8, pose:'auto', style:'noir', act:'late_set', lean:.6, smoke:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const md = (a, n) => ((a % n) + n) % n;
const frc = v => v - Math.floor(v);
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const sn = (tt, off) => { const f = Math.floor(tt), xq = tt - f; return (fr(f + off) * (1 - xq) + fr(f + 1 + off) * xq - .5) * 2; };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

const u = Math.min(width, height);
const sc = u * P.scale / 330;
const bt = K.beat * P.speed;
const sub = frc(bt);
const kick = K.pulse * .6 + A.bass * .85;
const en = P.energy * (.5 + .5 * K.intensity);
const H = md(P.hue, 360);
const riso = P.style === 'riso', neon = P.style === 'neon', sepia = P.style === 'sepia';
const noir = !riso && !neon && !sepia;

// ---- caches ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.fleck = [];
  for (let i = 0; i < 26; i++) S.fleck.push({
    x: (fr(i * 3 + 12) - .5) * 320, y: -20 - fr(i * 3 + 13) * 240,
    s: .8 + fr(i * 5 + 14) * 2, ph: fr(i * 7 + 15) * 6.2832
  });
}
if (!S.spr) {
  S.spr = createGraphics(64, 64);
  S.spr.noStroke();
  for (let r = 30; r > 0; r--) { S.spr.fill(255, 6); S.spr.ellipse(32, 32, r * 2.1, r * 2.1); }
}

// ---- pose program: sway groove, wail on the peaks ----
let pose = P.pose;
if (pose === 'auto') {
  const hot = P.act === 'after_hours' ? (K.section === 6) : (K.intensity > .72);
  pose = hot ? 'wail' : 'sway';
}
const wTgt = pose === 'wail' ? 1 : 0;
if (S.wail == null || !isFinite(S.wail)) S.wail = wTgt;
S.wail += (wTgt - S.wail) * .06;
const W = clp(S.wail, 0, 1);
const idle = pose === 'idle';
const tempoMul = P.act === 'after_hours' ? .6 : 1;

const rock = Math.sin(bt * Math.PI * tempoMul) * .06 * en * (idle ? .3 : 1);
const dip = kick * 4 * en * (idle ? .4 : 1);
const leanB = -.5 * P.lean * W + rock;
const vib = Math.sin(K.t * 26) * .014 * W * en;
const breath = Math.sin(K.t * .24) * .5 + K.swell * .5;
const tap = Math.max(0, Math.sin(sub * 6.2832)) * (2.5 * en);
const headYaw = idle ? sn(K.t * .15, 61) * .2 : 0;

const hipY = -58 + dip * .4;
const saxA = (idle ? .9 : .16) - W * .8 + vib;   // sax angle at mouth anchor
const rot2 = (px, py, th) => [px * Math.cos(th) - py * Math.sin(th), px * Math.sin(th) + py * Math.cos(th)];

// sax centerline (local: mouthpiece at origin, +y down the tube)
const PTS = [[0,0],[1,9],[2,20],[3,32],[4,42],[7,50],[12,54],[17,53],[21,47],[23,38],[23,30]];

// ---- style plumbing ----
let PASS = 1;
function FC(h, s, b, a) {
  if (PASS === 0) { noFill(); return; }
  if (PASS === 3) { fill(18, 78, 96, a * .8); return; }
  if (PASS === 4) { fill(202, 62, 88, a * .8); return; }
  if (neon) { fill(240, 45, 12, a); return; }
  if (sepia) { fill(32, 42, 34, a); return; }
  fill(h, s, b, a);
}
function SC(h, s, b, a, w) {
  if (PASS === 0) { stroke(H, 70, 100, 16); strokeWeight(w * 3); noFill(); return; }
  if (PASS === 3) { stroke(18, 78, 96, a * .8); }
  else if (PASS === 4) { stroke(202, 62, 88, a * .8); }
  else if (neon) { stroke(md(H + 30, 360), 75, 100, a); }
  else if (sepia) { stroke(28, 50, 26, a); }
  else stroke(h, s, b, a);
  strokeWeight(w);
}
const detailPass = () => PASS === 1 || PASS === 4;

// two-segment limb whose hand is GUARANTEED to land on target
function limbTo(sx, sy, hx, hy, bend, w, h2, s2, b2) {
  const mx2 = (sx + hx) / 2, my2 = (sy + hy) / 2;
  const dx = hx - sx, dy2 = hy - sy;
  const L = Math.sqrt(dx * dx + dy2 * dy2) + .001;
  const ex = mx2 - dy2 / L * bend, ey2 = my2 + dx / L * bend;
  SC(h2, s2, b2, 100, w);
  line(sx, sy, ex, ey2);
  line(ex, ey2, hx, hy);
}

function drawPlayer() {
  push();
  // legs + shoes (below coat hem)
  SC(235, 30, noir ? 22 : 30, 100, 6);
  line(-8, -30, -9, -2);
  line(8, -30, 9 - tap * .2, -2 - tap);
  noStroke(); FC(0, 0, 8, 100);
  rect(-15, -4, 13, 5, 2);
  push(); translate(9 - tap * .2, -2 - tap); rotate(-tap * .06); rect(-2, -2, 13, 5, 2); pop();
  // upper body pivots at the hip
  push();
  translate(0, hipY);
  rotate(leanB);
  // overcoat
  noStroke(); FC(232, 42, noir ? 15 : 40, 100);
  beginShape();
  vertex(-19, 30); vertex(19, 30);
  bezierVertex(16, 8, 14, -18, 13, -38);
  vertex(-13, -38);
  bezierVertex(-14, -18, -16, 8, -19, 30);
  endShape(CLOSE);
  // lapels
  if (detailPass()) {
    FC(232, 48, noir ? 24 : 55, 90);
    triangle(-2, -36, -12, -36, -5, -12);
    triangle(2, -36, 12, -36, 5, -12);
  }
  // head + fedora at shoulder top
  push();
  translate(headYaw * 6, -38);
  rotate(-W * .3 + headYaw * .3 + vib * 2);
  SC(22, 30, noir ? 55 : 70, 100, 3.4); line(0, 0, 0, -6);
  noStroke(); FC(22, 32, noir ? 62 : 78, 100);
  ellipse(0, -13, 15, 16);
  if (detailPass()) {   // jaw working + cheek puff while blowing
    FC(20, 34, noir ? 52 : 68, 95);
    ellipse(2.5, -8.5, 6 + kick * 2.5 * (idle ? 0 : 1), 5 + kick * 2 * (idle ? 0 : 1));
    fill(0, 0, 95, 55 + A.treble * 30);
    ellipse(-3.4, -14.5, 1.6, 1.8);   // one glint eye under the brim
  }
  // fedora
  FC(235, 35, noir ? 10 : 24, 100);
  ellipse(0, -18.5, 30, 7);
  arc(0, -19, 19, 17, Math.PI, 6.2832, CHORD);
  if (detailPass()) { FC(H, 45, noir ? 40 : 60, 90); rect(-9.5, -23.5, 19, 3.4, 1); }
  pop();
  // ---- the saxophone (anchored at the mouth) ----
  const mAx = 5, mAy = -46;
  push();
  translate(mAx, mAy);
  rotate(saxA);
  // main tube (double-stroked brass)
  SC(sepia ? 38 : 44, sepia ? 45 : 60, sepia ? 55 : 70, 100, 6.4);
  if (neon) SC(md(H + 40, 360), 80, 100, 95, 4);
  noFill();
  beginShape();
  curveVertex(PTS[0][0], PTS[0][1]);
  for (let i = 0; i < PTS.length; i++) curveVertex(PTS[i][0], PTS[i][1]);
  curveVertex(PTS[10][0], PTS[10][1]);
  endShape();
  if (detailPass() && !neon) {
    SC(46, 30, 92, 60, 2.2);
    beginShape();
    curveVertex(PTS[0][0] - 1, PTS[0][1]);
    for (let i = 0; i < PTS.length; i++) curveVertex(PTS[i][0] - 1, PTS[i][1]);
    curveVertex(PTS[10][0] - 1, PTS[10][1]);
    endShape();
  }
  noStroke();
  // bell
  push();
  translate(23, 26); rotate(-.18);
  FC(sepia ? 38 : 45, sepia ? 45 : 55, sepia ? 60 : 76, 100);
  ellipse(0, -1, 17, 21);
  if (detailPass() && !neon) { FC(46, 25, 90, 55); ellipse(-2.5, -3, 6, 11); }
  pop();
  // keys + fingering pattern (16th-note runs)
  for (let i = 0; i < 4; i++) {
    const kx = 2 + i * .7, ky = 20 + i * 6.4;
    const press = !idle && fr(Math.floor(bt * 4) * 13 + i * 7) > .45;
    if (press) { FC(46, 20, 96, 100); ellipse(kx, ky, 3.6, 3.6); }
    else { SC(46, 30, 88, 90, 1.1); noFill(); ellipse(kx, ky, 3.4, 3.4); noStroke(); }
  }
  // glint sweeping the tube (baseline sweep, flares on treble)
  const gi = frc(K.beat * .125) * (PTS.length - 1.01);
  const g0 = Math.floor(gi), gf = gi - g0;
  const gx2 = PTS[g0][0] * (1 - gf) + PTS[g0 + 1][0] * gf;
  const gy2 = PTS[g0][1] * (1 - gf) + PTS[g0 + 1][1] * gf;
  blendMode(ADD); noStroke();
  fill(48, 15, 100, clp(16 + A.treble * 60, 0, 70));
  ellipse(gx2, gy2, 5 + A.treble * 6, 2.4);
  // bell breath glow
  const [bwx, bwy] = [23, 30];
  fill(md(H + 20, 360), 30, 100, clp(6 + kick * 16 + W * 12, 0, 32));
  ellipse(bwx, bwy - 4, 26 + kick * 12 + W * 10, 30 + kick * 14);
  blendMode(BLEND);
  pop();
  // ---- arms: hands land on the horn (rotate key/bow points into body frame) ----
  const hand1 = rot2(3, 26, saxA);   // left hand on upper keys
  const hand2 = rot2(12, 52, saxA);  // right hand at the bow
  limbTo(-10, -34, mAx + hand1[0], mAy + hand1[1], 7, 5.2, 232, 42, noir ? 20 : 45);
  limbTo(11, -33, mAx + hand2[0], mAy + hand2[1], -8, 5.2, 232, 42, noir ? 20 : 45);
  noStroke(); FC(22, 32, noir ? 60 : 76, 100);
  ellipse(mAx + hand1[0], mAy + hand1[1], 7, 7);
  ellipse(mAx + hand2[0], mAy + hand2[1], 7.5, 7.5);
  // rim light (noir signature: one cold edge)
  if (noir && PASS === 1) {
    SC(H, 35, 95, 45 + kick * 20, 2);
    noFill();
    beginShape();
    vertex(-19, 30);
    bezierVertex(-16, 8, -14, -18, -13, -38);
    endShape();
    line(-13, -38, -6, -44);
    noStroke();
  }
  pop(); // upper body
  pop();
}

// ---- render ----
push();
translate(P.x * width + Math.sin(K.t * .13) * 8 * sc, P.y * height);
scale(sc);

// venetian-blind light bars (noir) / paper flecks (sepia+riso)
if (noir || neon) {
  push(); rotate(-.55);
  noStroke();
  const off = Math.sin(K.t * .05) * 30;
  for (let i = 0; i < 3; i++) {
    fill(H, 25, 70, 4 + K.swell * 2.5);
    rect(-250 + i * 95 + off, -260, 30, 440);
  }
  pop();
}
if (sepia || riso) {
  noStroke();
  for (let i = 0; i < 18; i++) {
    const fx2 = S.fleck[i];
    fill(38, 20, 80, 6 + (Math.sin(K.t * .4 + fx2.ph) * .5 + .5) * 6);
    ellipse(fx2.x, fx2.y, fx2.s, fx2.s);
  }
}

// spotlight pool on the floor
blendMode(ADD);
tint(neon ? H : noir ? H : 40, noir || neon ? 30 : 35, 90, clp(8 + K.intensity * 8 + A.rms * 20, 0, 26));
image(S.spr, -95, -60, 190, 90);
noTint();
blendMode(BLEND);

// shadow
noStroke(); fill(0, 0, 0, 45);
ellipse(2, 2, 74, 12);

// figure — style passes
if (neon) {
  PASS = 0; blendMode(ADD); drawPlayer(); blendMode(BLEND);
  PASS = 1; drawPlayer();
} else if (riso) {
  PASS = 3; push(); translate(-2.2, -1.5); drawPlayer(); pop();
  PASS = 4; push(); translate(2.2, 1.5); drawPlayer(); pop();
  PASS = 1;
} else {
  PASS = 1; drawPlayer();
}

// smoke curls off the bell (always drifting — the room breathes)
const bellW = rot2(23, 26, saxA);
const smX = 5 + bellW[0], smY = hipY - 46 + bellW[1];
const nsm = Math.floor(3 + P.density * 7 + P.smoke * 6);
noStroke();
for (let i = 0; i < nsm; i++) {
  const ag = frc(K.t * (.05 + .025 * fr(i + 60)) * (P.speed * .5 + .5) + fr(i * 3 + 7));
  const rise2 = ag * 105;
  const sway2 = Math.sin(ag * 5 + fr(i) * 6.283 + K.t * .2) * (5 + ag * 20);
  const al = Math.sin(ag * Math.PI) * (9 + P.smoke * 8 + A.rms * 25) * (1 - ag * .4);
  const sz = 7 + ag * 26;
  fill(md(H + 10, 360), 8, 92, clp(al, 0, 20));
  ellipse(smX + sway2, smY - 12 - rise2, sz, sz * .8);
  fill(md(H + 10, 360), 6, 96, clp(al * .6, 0, 14));
  ellipse(smX + sway2 * 1.2 + 4, smY - 16 - rise2, sz * .55, sz * .5);
}

// breath sparkle on hard blows
if (A.treble > .12 || K.pulse > .9) {
  blendMode(ADD);
  for (let i = 0; i < 5; i++) {
    const aa = fr(i * 19 + 3) * 6.2832 + K.t * .8;
    fill(48, 20, 100, clp((A.treble * 90 + 10) * fr(i + K.bar), 0, 50));
    ellipse(smX + Math.cos(aa) * (10 + i * 4), smY - 10 + Math.sin(aa) * 8, 2, 2);
  }
  blendMode(BLEND);
}
noStroke();
blendMode(BLEND);
pop();
